const input = $input.first().json;
const extractionId =
  typeof input.extractionId === 'string'
    ? input.extractionId.trim()
    : '';

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(extractionId)) {
  throw new Error(
    'INVALID_EXTRACTION_ID: extractionId must be a valid UUID.'
  );
}

return [{ json: { extractionId } }];

const input = $input.first().json;
const handoff = input.phase3Handoff ?? input;
const errors = [];

const isObject = (value) =>
  value !== null &&
  typeof value === 'object' &&
  !Array.isArray(value);

const requireObject = (value, path) => {
  if (!isObject(value)) {
    errors.push(`${path} must be an object`);
    return {};
  }

  return value;
};

const requireExactKeys = (value, path, requiredKeys) => {
  if (!isObject(value)) return;

  const allowed = new Set(requiredKeys);

  for (const key of requiredKeys) {
    if (!Object.hasOwn(value, key)) {
      errors.push(`${path}.${key} is required`);
    }
  }

  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) {
      errors.push(`${path}.${key} is not allowed`);
    }
  }
};

const requireText = (value, path, minimumLength = 1) => {
  if (
    typeof value !== 'string' ||
    value.trim().length < minimumLength
  ) {
    errors.push(`${path} must contain at least ${minimumLength} characters`);
    return '';
  }

  return value.trim();
};

const requireBoolean = (value, path) => {
  if (typeof value !== 'boolean') {
    errors.push(`${path} must be boolean`);
  }
};

const requireNumber = (value, path, minimum, maximum) => {
  if (
    typeof value !== 'number' ||
    !Number.isFinite(value) ||
    value < minimum ||
    value > maximum
  ) {
    errors.push(`${path} must be a number from ${minimum} to ${maximum}`);
  }
};

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const requireUuid = (value, path) => {
  if (!uuidPattern.test(String(value ?? ''))) {
    errors.push(`${path} must be UUID`);
  }
};

const requireDateTime = (value, path) => {
  if (
    typeof value !== 'string' ||
    value.trim() === '' ||
    Number.isNaN(Date.parse(value))
  ) {
    errors.push(`${path} must be a valid date-time string`);
  }
};

const root = requireObject(handoff, 'handoff');

const topLevelKeys = [
  'contract',
  'contractVersion',
  'requestId',
  'assessmentId',
  'extractionId',
  'candidate',
  'assessmentContext',
  'gradeGuide',
  'score',
  'decision',
  'dimensionAssessments',
  'reviewReasons',
  'modelWarnings',
  'assessmentSummary',
  'execution',
  'metadata',
];

requireExactKeys(root, 'handoff', topLevelKeys);

if (root.contract !== 'talentai.phase3.assessment-handoff') {
  errors.push('unsupported contract');
}

if (root.contractVersion !== '1.0.0') {
  errors.push('unsupported contractVersion');
}

requireUuid(root.requestId, 'requestId');
requireUuid(root.assessmentId, 'assessmentId');
requireUuid(root.extractionId, 'extractionId');

const candidate = requireObject(root.candidate, 'candidate');
requireExactKeys(candidate, 'candidate', ['fullName']);
requireText(candidate.fullName, 'candidate.fullName');

const assessmentContext = requireObject(
  root.assessmentContext,
  'assessmentContext'
);
requireExactKeys(assessmentContext, 'assessmentContext', [
  'positionCode',
  'targetGradeCode',
  'jobDescription',
]);

if (assessmentContext.positionCode !== 'JAVA_BACKEND') {
  errors.push('unsupported assessmentContext.positionCode');
}

if (
  !['JUNIOR', 'MID', 'SENIOR'].includes(
    assessmentContext.targetGradeCode
  )
) {
  errors.push('unsupported assessmentContext.targetGradeCode');
}

requireText(
  assessmentContext.jobDescription,
  'assessmentContext.jobDescription',
  30
);

const gradeGuide = requireObject(root.gradeGuide, 'gradeGuide');
requireExactKeys(gradeGuide, 'gradeGuide', ['id', 'version']);
requireUuid(gradeGuide.id, 'gradeGuide.id');
requireText(gradeGuide.version, 'gradeGuide.version');

const score = requireObject(root.score, 'score');
requireExactKeys(score, 'score', [
  'overall',
  'minimumRequired',
  'thresholdMet',
  'mandatoryDimensionsMet',
]);
requireNumber(score.overall, 'score.overall', 0, 100);
requireNumber(score.minimumRequired, 'score.minimumRequired', 0, 100);
requireBoolean(score.thresholdMet, 'score.thresholdMet');
requireBoolean(
  score.mandatoryDimensionsMet,
  'score.mandatoryDimensionsMet'
);

const decisions = new Set([
  'MEETS_TARGET',
  'BELOW_TARGET',
  'REVIEW_REQUIRED',
]);

if (!decisions.has(root.decision)) {
  errors.push('unsupported decision');
}

for (const [value, path] of [
  [root.reviewReasons, 'reviewReasons'],
  [root.modelWarnings, 'modelWarnings'],
]) {
  if (!Array.isArray(value)) {
    errors.push(`${path} must be an array`);
    continue;
  }

  for (const [index, item] of value.entries()) {
    requireText(item, `${path}[${index}]`);
  }
}

requireText(root.assessmentSummary, 'assessmentSummary');

const requiredDimensionCodes = new Set([
  'JAVA_CORE',
  'SPRING_ECOSYSTEM',
  'DATABASE',
  'DISTRIBUTED_SYSTEMS',
  'TESTING',
  'SOFTWARE_ARCHITECTURE',
  'OBSERVABILITY_DEVOPS',
]);
const confidenceValues = new Set(['HIGH', 'MEDIUM', 'LOW']);
const evidenceSources = new Set([
  'PROFILE_SKILL',
  'WORK_EXPERIENCE',
  'EDUCATION',
  'WARNING',
  'OTHER',
]);
const dimensionKeys = [
  'code',
  'title',
  'weight',
  'mandatory',
  'modelScore',
  'effectiveScore',
  'confidence',
  'confidenceAccepted',
  'weightedScore',
  'minimumRequired',
  'minimumMet',
  'evidence',
  'rationale',
];
const receivedDimensionCodes = new Set();

if (
  !Array.isArray(root.dimensionAssessments) ||
  root.dimensionAssessments.length !== requiredDimensionCodes.size
) {
  errors.push('dimensionAssessments must contain exactly 7 entries');
} else {
  for (const [index, rawDimension] of root.dimensionAssessments.entries()) {
    const path = `dimensionAssessments[${index}]`;
    const dimension = requireObject(rawDimension, path);

    requireExactKeys(dimension, path, dimensionKeys);

    if (!requiredDimensionCodes.has(dimension.code)) {
      errors.push(`${path}.code is unsupported`);
    } else if (receivedDimensionCodes.has(dimension.code)) {
      errors.push(`${path}.code is duplicated`);
    } else {
      receivedDimensionCodes.add(dimension.code);
    }

    requireText(dimension.title, `${path}.title`);

    if (
      !Number.isInteger(dimension.weight) ||
      dimension.weight < 0 ||
      dimension.weight > 100
    ) {
      errors.push(`${path}.weight must be an integer from 0 to 100`);
    }

    requireBoolean(dimension.mandatory, `${path}.mandatory`);

    for (const field of ['modelScore', 'effectiveScore']) {
      if (
        !Number.isInteger(dimension[field]) ||
        dimension[field] < 0 ||
        dimension[field] > 4
      ) {
        errors.push(`${path}.${field} must be an integer from 0 to 4`);
      }
    }

    if (!confidenceValues.has(dimension.confidence)) {
      errors.push(`${path}.confidence is unsupported`);
    }

    requireBoolean(
      dimension.confidenceAccepted,
      `${path}.confidenceAccepted`
    );
    requireNumber(
      dimension.weightedScore,
      `${path}.weightedScore`,
      0,
      100
    );

    if (
      dimension.minimumRequired !== null &&
      (
        !Number.isInteger(dimension.minimumRequired) ||
        dimension.minimumRequired < 0 ||
        dimension.minimumRequired > 4
      )
    ) {
      errors.push(
        `${path}.minimumRequired must be null or an integer from 0 to 4`
      );
    }

    requireBoolean(dimension.minimumMet, `${path}.minimumMet`);

    if (!Array.isArray(dimension.evidence)) {
      errors.push(`${path}.evidence must be an array`);
    } else {
      if (dimension.evidence.length > 5) {
        errors.push(`${path}.evidence must contain at most 5 entries`);
      }

      if (dimension.modelScore > 0 && dimension.evidence.length === 0) {
        errors.push(`${path} positive score lacks evidence`);
      }

      for (const [evidenceIndex, rawEvidence] of
        dimension.evidence.entries()) {
        const evidencePath = `${path}.evidence[${evidenceIndex}]`;
        const evidence = requireObject(rawEvidence, evidencePath);

        requireExactKeys(evidence, evidencePath, ['quote', 'source']);
        requireText(evidence.quote, `${evidencePath}.quote`);

        if (!evidenceSources.has(evidence.source)) {
          errors.push(`${evidencePath}.source is unsupported`);
        }
      }
    }

    requireText(dimension.rationale, `${path}.rationale`);
  }
}

if (receivedDimensionCodes.size !== requiredDimensionCodes.size) {
  errors.push('dimensionAssessments has an incomplete dimension set');
}

const execution = requireObject(root.execution, 'execution');
requireExactKeys(execution, 'execution', [
  'attemptCount',
  'status',
  'replayed',
  'startedAt',
  'completedAt',
]);

if (!Number.isInteger(execution.attemptCount) || execution.attemptCount < 1) {
  errors.push('execution.attemptCount must be a positive integer');
}

if (execution.status !== 'COMPLETED') {
  errors.push('execution.status must be COMPLETED');
}

requireBoolean(execution.replayed, 'execution.replayed');
requireDateTime(execution.startedAt, 'execution.startedAt');
requireDateTime(execution.completedAt, 'execution.completedAt');

const metadata = requireObject(root.metadata, 'metadata');
requireExactKeys(metadata, 'metadata', [
  'scoringModel',
  'promptVersion',
  'engineVersion',
  'assessmentStatus',
  'createdAt',
]);
requireText(metadata.scoringModel, 'metadata.scoringModel');
requireText(metadata.promptVersion, 'metadata.promptVersion');
requireText(metadata.engineVersion, 'metadata.engineVersion');

if (metadata.assessmentStatus !== 'COMPLETED') {
  errors.push('metadata.assessmentStatus must be COMPLETED');
}

requireDateTime(metadata.createdAt, 'metadata.createdAt');

if (
  root.decision === 'MEETS_TARGET' &&
  (
    score.thresholdMet !== true ||
    score.mandatoryDimensionsMet !== true ||
    root.reviewReasons?.length !== 0
  )
) {
  errors.push('MEETS_TARGET invariants are not satisfied');
}

if (
  root.decision === 'REVIEW_REQUIRED' &&
  root.reviewReasons?.length === 0
) {
  errors.push('REVIEW_REQUIRED requires at least one review reason');
}

if (errors.length > 0) {
  throw new Error(
    `INVALID_PHASE3_HANDOFF: ${errors.join('; ')}`
  );
}

const minimumDimensionLevels = Object.fromEntries(
  root.dimensionAssessments
    .filter((dimension) => dimension.minimumRequired !== null)
    .map((dimension) => [
      dimension.code,
      dimension.minimumRequired,
    ])
);

const targetGrade = {
  code: assessmentContext.targetGradeCode,
  label: assessmentContext.targetGradeCode,
  minimumOverallScore: score.minimumRequired,
  minimumDimensionLevels,
};

return [
  {
    json: {
      phase3Handoff: root,
      correlation: {
        contractVersion: root.contractVersion,
        requestId: root.requestId,
        assessmentId: root.assessmentId,
        extractionId: root.extractionId,
      },
      extraction: {
        id: root.extractionId,
        positionCode: assessmentContext.positionCode,
        targetGradeCode: assessmentContext.targetGradeCode,
        jobDescription: assessmentContext.jobDescription,
      },
      candidate: {
        fullName: candidate.fullName.trim(),
      },
      gradeGuide: {
        id: gradeGuide.id,
        version: gradeGuide.version,
        targetGrade,
        grades: [targetGrade],
        dimensions: root.dimensionAssessments.map((dimension) => ({
          code: dimension.code,
          title: dimension.title,
          weight: dimension.weight,
          mandatory: dimension.mandatory,
          minimumRequired: dimension.minimumRequired,
        })),
        scoringScale: [
          { score: 0, meaning: 'NO_USABLE_EVIDENCE' },
          { score: 1, meaning: 'LIMITED_OR_VAGUE' },
          { score: 2, meaning: 'PRACTICAL_AND_CONCRETE' },
          { score: 3, meaning: 'ADVANCED_WITH_TRADE_OFFS' },
          { score: 4, meaning: 'LEADERSHIP_OR_CROSS_CUTTING_OWNERSHIP' },
        ],
      },
      resumeGrade: {
        assessmentId: root.assessmentId,
        decision: root.decision,
        overallScore: score.overall,
        minimumOverallScore: score.minimumRequired,
        thresholdMet: score.thresholdMet,
        mandatoryDimensionsMet: score.mandatoryDimensionsMet,
        assessedAt: metadata.createdAt,
        summary: root.assessmentSummary,
        reviewReasons: root.reviewReasons,
        modelWarnings: root.modelWarnings,
        dimensions: root.dimensionAssessments,
      },
    },
  },
];

const interviewConfiguration = {
  schemaVersion: '1.0',

  rounds: {
    first: {
      totalQuestions: 20,
      singleChoice: 6,
      multiChoice: 6,
      explanatory: 8,
    },

    followUp: {
      totalQuestions: 10,
      singleChoice: 3,
      multiChoice: 3,
      explanatory: 4,
    },
  },
};

return [
  {
    json: interviewConfiguration,
  },
];

parameters.inputSchema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://talentai.local/schemas/interview-question-plan-v1.schema.json",
  "title": "TalentAI Interview Question Plan v1",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "interviewPlanTitle",
    "questions",
    "generationWarnings"
  ],
  "properties": {
    "schemaVersion": {
      "const": "1.0"
    },
    "interviewPlanTitle": {
      "type": "string",
      "minLength": 1,
      "maxLength": 200
    },
    "questions": {
      "type": "array",
      "minItems": 1,
      "maxItems": 20,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "id",
          "dimensionCode",
          "type",
          "questionText",
          "options"
        ],
        "properties": {
          "id": {
            "type": "string",
            "minLength": 1,
            "maxLength": 40
          },
          "dimensionCode": {
            "type": "string",
            "enum": [
              "JAVA_CORE",
              "SPRING_ECOSYSTEM",
              "DATABASE",
              "DISTRIBUTED_SYSTEMS",
              "TESTING",
              "SOFTWARE_ARCHITECTURE",
              "OBSERVABILITY_DEVOPS"
            ]
          },
          "type": {
            "type": "string",
            "enum": [
              "single_choice",
              "multi_choice",
              "explanatory"
            ]
          },
          "questionText": {
            "type": "string",
            "minLength": 10,
            "maxLength": 600
          },
          "options": {
            "type": "array",
            "maxItems": 6,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "label",
                "score"
              ],
              "properties": {
                "label": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 300
                },
                "score": {
                  "type": "integer",
                  "minimum": 0,
                  "maximum": 4
                }
              }
            }
          }
        }
      }
    },
    "generationWarnings": {
      "type": "array",
      "maxItems": 20,
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 1000
      }
    }
  }
}

parameters.jsCode:
const chainResult = $input.first().json;

let questionPlan =
  chainResult.output ??
  chainResult.text ??
  chainResult.response ??
  chainResult;

if (
  questionPlan &&
  typeof questionPlan === 'object' &&
  questionPlan.output &&
  !questionPlan.questions
) {
  questionPlan = questionPlan.output;
}

if (typeof questionPlan === 'string') {
  try {
    questionPlan = JSON.parse(questionPlan);
  } catch (error) {
    throw new Error(
      `INVALID_INTERVIEW_PLAN_JSON: ${error.message}`
    );
  }
}

const promptContext =
  $('Build Interview Question Prompt').first().json;

const interviewContext =
  promptContext.interviewContext;

const roundConfig =
  promptContext.config.rounds.first;

const expected = {
  total: Number(roundConfig.totalQuestions),
  single_choice: Number(roundConfig.singleChoice),
  multi_choice: Number(roundConfig.multiChoice),
  explanatory: Number(roundConfig.explanatory),
};

const configErrors = [];

if (
  !Number.isInteger(expected.total) ||
  expected.total < 1 ||
  expected.total > 20
) {
  configErrors.push('totalQuestions must be an integer from 1 to 20');
}

for (const type of ['single_choice', 'multi_choice', 'explanatory']) {
  if (!Number.isInteger(expected[type]) || expected[type] < 0) {
    configErrors.push(`${type} count must be a non-negative integer`);
  }
}

if (
  expected.single_choice +
    expected.multi_choice +
    expected.explanatory !==
  expected.total
) {
  configErrors.push('question type counts must add up to totalQuestions');
}

if (configErrors.length > 0) {
  throw new Error(
    `INVALID_INTERVIEW_CONFIGURATION: ${configErrors.join("; ")}`
  );
}

const dimensions =
  interviewContext.gradeGuide.dimensions;

const dimensionCodes = dimensions.map(
  (dimension) => dimension.code
);

const errors = [];

if (
  !questionPlan ||
  typeof questionPlan !== 'object' ||
  Array.isArray(questionPlan)
) {
  errors.push('question plan must be an object');
}

const questions = Array.isArray(questionPlan?.questions)
  ? questionPlan.questions
  : [];

if (questions.length !== expected.total) {
  errors.push(
    `expected exactly ${expected.total} questions, received ${questions.length}`
  );
}

const sanitizedQuestions = [];
const usedIds = new Set();
const typeCounts = {
  single_choice: 0,
  multi_choice: 0,
  explanatory: 0,
};
const dimensionCounts = {};

for (const [index, question] of questions.entries()) {
  const questionNumber = index + 1;

  const rawId = String(question?.id ?? '').trim();
  const id =
    rawId.replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 40) ||
    `Q${questionNumber}`;

  if (usedIds.has(id)) {
    errors.push(`duplicate question id: ${id}`);
    continue;
  }

  usedIds.add(id);

  const dimensionCode = String(question?.dimensionCode ?? '').trim();

  if (!dimensionCodes.includes(dimensionCode)) {
    errors.push(
      `${id}: unknown dimensionCode ${dimensionCode || 'empty'}`
    );
    continue;
  }

  const type = String(question?.type ?? '').trim();

  if (!(type in typeCounts)) {
    errors.push(
      `${id}: type must be single_choice, multi_choice or explanatory`
    );
    continue;
  }

  const questionText = String(question?.questionText ?? '').trim();

  if (questionText.length < 10) {
    errors.push(`${id}: questionText is too short`);
    continue;
  }

  typeCounts[type] += 1;

  dimensionCounts[dimensionCode] =
    (dimensionCounts[dimensionCode] ?? 0) + 1;

  const rawOptions = Array.isArray(question?.options)
    ? question.options
    : [];

  if (type === 'explanatory') {
    if (rawOptions.length > 0) {
      errors.push(
        `${id}: explanatory questions must not define options`
      );
      continue;
    }

    sanitizedQuestions.push({
      id,
      dimensionCode,
      type,
      questionText,
      options: [],
    });

    continue;
  }

  const minimumOptions = type === 'single_choice' ? 3 : 4;
  const maximumOptions = type === 'single_choice' ? 4 : 6;

  if (
    rawOptions.length < minimumOptions ||
    rawOptions.length > maximumOptions
  ) {
    errors.push(
      `${id}: ${type} requires ${minimumOptions} to ${maximumOptions} options`
    );
    continue;
  }

  const labels = new Set();
  const options = [];

  for (const option of rawOptions) {
    const label = String(option?.label ?? '').trim();

    if (!label) {
      errors.push(`${id}: option label is empty`);
      continue;
    }

    if (labels.has(label)) {
      errors.push(`${id}: duplicate option label`);
      continue;
    }

    labels.add(label);

    const score = Number(option?.score);

    if (!Number.isInteger(score) || score < 0 || score > 4) {
      errors.push(
        `${id}: option scores must be integers from 0 to 4`
      );
      continue;
    }

    options.push({ label, score });
  }

  if (options.length !== rawOptions.length) {
    continue;
  }

  const distinctScores = new Set(
    options.map((option) => option.score)
  );

  if (distinctScores.size < 2) {
    errors.push(
      `${id}: options must contain at least two distinct scores`
    );
    continue;
  }

  sanitizedQuestions.push({
    id,
    dimensionCode,
    type,
    questionText,
    options,
  });
}

if (sanitizedQuestions.length !== expected.total) {
  errors.push(
    `only ${sanitizedQuestions.length} of ${expected.total} questions survived validation`
  );
}

for (const type of Object.keys(typeCounts)) {
  if (typeCounts[type] !== expected[type]) {
    errors.push(
      `expected exactly ${expected[type]} ${type} questions, received ${typeCounts[type]}`
    );
  }
}

for (const dimensionCode of dimensionCodes) {
  const count = dimensionCounts[dimensionCode] ?? 0;

  if (count < 2 || count > 4) {
    errors.push(
      `${dimensionCode}: received ${count} questions, expected between 2 and 4`
    );
  }
}

if (errors.length > 0) {
  throw new Error(`INVALID_INTERVIEW_PLAN: ${errors.join("; ")}`);
}

const formFields = sanitizedQuestions.map(
  (question, index) => {
    const fieldLabel =
      `${index + 1}. ${question.questionText}`;

    if (question.type === 'explanatory') {
      return {
        fieldLabel,
        fieldName: `q_${question.id}`,
        fieldType: 'textarea',
        placeholder: 'پاسخ خود را همین‌جا بنویسید…',
        requiredField: true,
      };
    }

    return {
      fieldLabel,
      fieldName: `q_${question.id}`,
      fieldType: question.type === 'multi_choice' ? 'checkbox' : 'radio',
      fieldOptions: {
        values: question.options.map(
          (option) => ({ option: option.label })
        ),
      },
      requiredField: true,
    };
  }
);

const candidateName =
  interviewContext.candidate.fullName;

return [
  {
    json: {
      interviewContext,

      questionPlan: {
        schemaVersion: '1.0',
        round: 'first',
        title: String(
          questionPlan.interviewPlanTitle ?? 'TalentAI Technical Interview'
        ).trim(),
        questions: sanitizedQuestions,
        generationWarnings: Array.isArray(
          questionPlan.generationWarnings
        )
          ? questionPlan.generationWarnings.map(String)
          : [],
      },

      formFields,

      interviewFormTitle: 'مصاحبه فنی TalentAI — مرحله اول',

      interviewFormDescription:
        `${candidateName} عزیز، لطفاً به هر ${expected.total} سؤال پاسخ بدهید و سپس فرم را ارسال کنید.` +
        ` این مجموعه شامل ${expected.single_choice} سؤال چندگزینه‌ای تک‌انتخابی، ${expected.multi_choice} سؤال چندگزینه‌ای چندانتخابی و ${expected.explanatory} سؤال تشریحی است.` +
        ' در سؤال‌های چندانتخابی می‌توانید چند گزینه را انتخاب کنید.',
    },
  },
];

const formAnswers = $input.first().json;

const planContext =
  $('Validate Interview Questions').first().json;

const interviewContext =
  planContext.interviewContext;

const questionPlan =
  planContext.questionPlan;

const errors = [];
const answerRecords = [];

const toAnswerList = (value) => {
  if (Array.isArray(value)) {
    return value.map((item) => String(item ?? '').trim()).filter(Boolean);
  }

  const text = String(value ?? '').trim();
  return text ? [text] : [];
};

for (const question of questionPlan.questions) {
  const answerList = toAnswerList(formAnswers[`q_${question.id}`]);

  if (answerList.length === 0) {
    errors.push(`${question.id}: answer is empty`);
    continue;
  }

  if (question.type === 'explanatory') {
    answerRecords.push({
      round: 'first',
      id: question.id,
      dimensionCode: question.dimensionCode,
      type: question.type,
      questionText: question.questionText,
      answerLabels: [],
      answerText: answerList.join('\n'),
      mcqScore: null,
      llmScore: null,
      llmRationale: '',
      finalScore: null,
    });

    continue;
  }

  const unknownOption = answerList.find(
    (label) => !question.options.some((option) => option.label === label)
  );

  if (unknownOption !== undefined) {
    errors.push(
      `${question.id}: submitted option does not match the questionnaire`
    );
    continue;
  }

  if (question.type === 'single_choice' && answerList.length > 1) {
    errors.push(`${question.id}: only one option can be selected`);
    continue;
  }

  const selectedScores = answerList.map(
    (label) =>
      question.options.find((option) => option.label === label).score
  );

  const mcqScore =
    question.type === 'single_choice'
      ? selectedScores[0]
      : Math.round(
          (selectedScores.reduce(
            (total, score) => total + score,
            0
          ) /
            selectedScores.length) *
            100
        ) / 100;

  answerRecords.push({
    round: 'first',
    id: question.id,
    dimensionCode: question.dimensionCode,
    type: question.type,
    questionText: question.questionText,
    answerLabels: answerList,
    answerText: '',
    mcqScore,
    llmScore: null,
    llmRationale: '',
    finalScore: mcqScore,
  });
}

if (errors.length > 0) {
  throw new Error(`INVALID_INTERVIEW_ANSWERS: ${errors.join("; ")}`);
}

return [
  {
    json: {
      interviewContext,
      answerRecords,
    },
  },
];

