const chainResult = $input.first().json;

let scoringResult =
  chainResult.output ??
  chainResult.text ??
  chainResult.response ??
  chainResult;

if (
  scoringResult &&
  typeof scoringResult === 'object' &&
  scoringResult.output &&
  !scoringResult.questionScores
) {
  scoringResult = scoringResult.output;
}

if (typeof scoringResult === 'string') {
  try {
    scoringResult = JSON.parse(scoringResult);
  } catch (error) {
    throw new Error(
      `INVALID_ANSWER_SCORING_JSON: ${error.message}`
    );
  }
}

const promptContext =
  $('Build Answer Scoring Prompt').first().json;

const answerRecords =
  promptContext.answerRecords;

const explanatoryRecords = answerRecords.filter(
  (record) => record.type === 'explanatory'
);

const errors = [];

if (
  !scoringResult ||
  typeof scoringResult !== 'object' ||
  Array.isArray(scoringResult)
) {
  errors.push('scoring result must be an object');
}

const questionScores = Array.isArray(
  scoringResult?.questionScores
)
  ? scoringResult.questionScores
  : [];

const scoreById = new Map();

for (const item of questionScores) {
  const id = String(item?.id ?? '').trim();
  const score = Number(item?.score);

  if (scoreById.has(id)) {
    errors.push(`duplicate score for ${id}`);
    continue;
  }

  if (!Number.isInteger(score) || score < 0 || score > 4) {
    errors.push(
      `${id || 'unknown'}: score must be an integer from 0 to 4`
    );
    continue;
  }

  if (
    typeof item?.rationale !== 'string' ||
    !item.rationale.trim()
  ) {
    errors.push(`${id}: rationale is required`);
    continue;
  }

  scoreById.set(id, {
    score,
    rationale: String(item.rationale).trim(),
  });
}

const mergedRecords = answerRecords.map(
  (record) => {
    if (record.type !== 'explanatory') {
      return { ...record };
    }

    const scored = scoreById.get(record.id);

    if (!scored) {
      return { ...record };
    }

    return {
      ...record,
      llmScore: scored.score,
      llmRationale: scored.rationale,
      finalScore: scored.score,
    };
  }
);

const scoredExplanatoryCount = mergedRecords.filter(
  (record) => record.type === 'explanatory' &&
  Number.isInteger(record.finalScore)
).length;

if (scoredExplanatoryCount !== explanatoryRecords.length) {
  errors.push('not every explanatory answer received a valid score');
}

if (!Array.isArray(scoringResult?.warnings)) {
  errors.push('warnings must be an array');
}

if (
  typeof scoringResult?.interviewSummary !== 'string' ||
  !scoringResult.interviewSummary.trim()
) {
  errors.push('interviewSummary is required');
}

if (errors.length > 0) {
  throw new Error(`INVALID_ANSWER_SCORES: ${errors.join("; ")}`);
}

const warnings = scoringResult.warnings.map(String).slice(0, 20);

if (scoreById.size > explanatoryRecords.length) {
  warnings.push('The model returned scores for unknown question ids; they were ignored.');
}

return [
  {
    json: {
      interviewContext: promptContext.interviewContext,
      answerRecords: mergedRecords,
      answerScoring: {
        schemaVersion: '1.0',
        interviewSummary: String(
          scoringResult.interviewSummary
        ).trim(),
        warnings,
      },
    },
  },
];

const validated = $input.first().json;

const interviewContext =
  validated.interviewContext;

const answerRecords =
  validated.answerRecords;

const gradeGuide =
  interviewContext.gradeGuide;

const dimensions =
  gradeGuide.dimensions;

const grades = Array.isArray(gradeGuide.grades)
  ? gradeGuide.grades
  : [];

const resumeDimensionByCode = new Map(
  interviewContext.resumeGrade.dimensions.map(
    (dimension) => [dimension.code, dimension]
  )
);

const dimensionScores = [];

for (const dimension of dimensions) {
  const dimensionRecords = answerRecords.filter(
    (record) => record.dimensionCode === dimension.code
  );

  const questionScores = dimensionRecords.map(
    (record) => Number(record.finalScore)
  );

  if (questionScores.length === 0) {
    throw new Error(
      `NO_INTERVIEW_QUESTIONS_FOR_DIMENSION: ${dimension.code}`
    );
  }

  const average =
    questionScores.reduce(
      (total, score) => total + score,
      0
    ) / questionScores.length;

  const interviewScore =
    Math.round(average * 100) / 100;

  const resumeDimension =
    resumeDimensionByCode.get(dimension.code);

  const roundQuestionCounts = { first: 0, followUp: 0 };

  for (const record of dimensionRecords) {
    roundQuestionCounts[record.round] += 1;
  }

  dimensionScores.push({
    code: dimension.code,
    title: dimension.title,
    weight: Number(dimension.weight),
    questionCount: questionScores.length,
    roundQuestionCounts,
    interviewScore,
    resumeScore:
      resumeDimension === undefined
        ? null
        : Number(resumeDimension.effectiveScore),
    delta:
      resumeDimension === undefined
        ? null
        : Math.round(
            (interviewScore -
              Number(resumeDimension.effectiveScore)) *
            100
          ) / 100,
  });
}

const overallScore =
  Math.round(
    dimensionScores.reduce(
      (total, dimension) =>
        total + (dimension.interviewScore / 4) * dimension.weight,
      0
    ) * 100
  ) / 100;

const gradeChecks = [];

for (const grade of grades) {
  const minimumLevels =
    grade.minimumDimensionLevels ?? {};

  const dimensionChecks = Object.entries(minimumLevels).map(
    ([code, minimumRequired]) => {
      const dimension = dimensionScores.find(
        (item) => item.code === code
      );

      if (!dimension) {
        throw new Error(
          `GRADE_DIMENSION_NOT_FOUND: ${code}`
        );
      }

      return {
        code,
        minimumRequired: Number(minimumRequired),
        interviewScore: dimension.interviewScore,
        met:
          dimension.interviewScore >=
          Number(minimumRequired),
      };
    }
  );

  const overallMet =
    overallScore >= Number(grade.minimumOverallScore);

  gradeChecks.push({
    code: grade.code,
    label: grade.label,
    minimumOverallScore: Number(grade.minimumOverallScore),
    overallMet,
    dimensionChecks,
    met:
      overallMet &&
      dimensionChecks.every((check) => check.met),
  });
}

const metGrades = gradeChecks.filter(
  (check) => check.met
);

const assigned =
  metGrades.length > 0
    ? metGrades.reduce(
        (best, check) =>
          Number(check.minimumOverallScore) >=
          Number(best.minimumOverallScore)
            ? check
            : best
      )
    : null;

const assignedGrade = assigned
  ? {
      code: assigned.code,
      label: assigned.label,
      minimumOverallScore: assigned.minimumOverallScore,
      basis: 'INTERVIEW_ANSWERS',
    }
  : {
      code: 'NO_MATCH',
      label: 'کمتر از حداقل همه گریدها',
      minimumOverallScore: null,
      basis: 'INTERVIEW_ANSWERS',
    };

const workflowExecutionId =
  String($execution.id);

if (!workflowExecutionId) {
  throw new Error(
    'WORKFLOW_EXECUTION_ID_MISSING'
  );
}

return [
  {
    json: {
      schemaVersion: '1.0',

      interviewExecutionId: workflowExecutionId,

      extraction: interviewContext.extraction,

      candidate: interviewContext.candidate,

      gradeGuide: {
        id: gradeGuide.id,
        version: gradeGuide.version,
      },

      assignedGrade,

      score: {
        overall: overallScore,
        scale: '0-100',
        dimensions: dimensionScores,
      },

      gradeChecks,

      interview: {
        questionCount: answerRecords.length,
        firstRoundQuestionCount: answerRecords.filter(
          (record) => record.round === 'first'
        ).length,
        followUpQuestionCount: answerRecords.filter(
          (record) => record.round === 'followUp'
        ).length,
        summary:
          validated.answerScoring.interviewSummary,
        warnings:
          validated.answerScoring.warnings,
      },

      resumeGrade: {
        assessmentId:
          interviewContext.resumeGrade.assessmentId,
        decision:
          interviewContext.resumeGrade.decision,
        overallScore:
          interviewContext.resumeGrade.overallScore,
        minimumOverallScore:
          interviewContext.resumeGrade.minimumOverallScore,
      },

      metadata: {
        questionModel: 'gpt-5.6-sol',
        scoringModel: 'gpt-5.6-sol',
        promptVersions: {
          questions: '1.0',
          answers: '1.0',
        },
        engineVersion: '1.0',
        createdAt: new Date().toISOString(),
      },
    },
  },
];

const result = $input.first().json;

const dimensionLines = result.score.dimensions.map(
  (dimension) => {
    const resumeScore =
      dimension.resumeScore === null
        ? 'ناموجود'
        : `${dimension.resumeScore}`;

    const roundCounts =
      `مرحله اول ${dimension.roundQuestionCounts.first}` +
      `، تکمیلی ${dimension.roundQuestionCounts.followUp}`;

    return `- ${dimension.code} (${dimension.title}): مصاحبه ${dimension.interviewScore}/4 (رزومه ${resumeScore}/4) | سوالات: ${roundCounts}`;
  }
);

const gradeLines = result.gradeChecks.map(
  (check) =>
    `- ${check.code}: ${check.met ? 'برآورده' : 'برآورده نشده'} (حداقل امتیاز کل ${check.minimumOverallScore})`
);

const message = [
  `نام کاندید: ${result.candidate.fullName}`,
  `عنوان شغل: ${result.extraction.positionCode}`,
  `گرید هدف: ${result.extraction.targetGradeCode}`,
  '',
  `گرید نهایی منتسب: ${result.assignedGrade.code} (${result.assignedGrade.label})`,
  `امتیاز مصاحبه: ${result.score.overall} از 100`,
  `گرید رزومه: ${result.resumeGrade.overallScore} از 100 (${result.resumeGrade.decision})`,
  '',
  'خلاصه ارزیابی:',
  result.interview.summary,
  '',
  'مقایسه ابعاد:',
  ...dimensionLines,
  '',
  'بررسی گریدها:',
  ...gradeLines,
  '',
  `تعداد سوالات: مرحله اول ${result.interview.firstRoundQuestionCount}، مرحله تکمیلی ${result.interview.followUpQuestionCount}`,
  `شناسه مصاحبه: ${result.interviewExecutionId}`,
].join('\n');

return [
  {
    json: {
      ...result,
      finalGradeMessage: message,
    },
  },
];

const resolved = $input.first().json;

if (resolved.resolutionStatus !== 'RESOLVED') {
  throw new Error(
    `UNEXPECTED_RESOLUTION_STATUS: ${resolved.resolutionStatus}`
  );
}

const asIsoDate = (value, fieldName) => {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    throw new Error(
      `INVALID_PHASE3_HANDOFF_SOURCE: ${fieldName} must be a valid date-time.`
    );
  }

  return date.toISOString();
};

const candidate =
  resolved.candidate &&
  typeof resolved.candidate === 'object' &&
  !Array.isArray(resolved.candidate)
    ? resolved.candidate
    : {};

return [
  {
    json: {
      phase3Handoff: {
        contract: 'talentai.phase3.assessment-handoff',
        contractVersion: '1.0.0',
        requestId: resolved.requestId,
        assessmentId: resolved.assessmentId,
        extractionId: resolved.extractionId,
        candidate: {
          fullName: String(candidate.fullName ?? '').trim(),
        },
        assessmentContext: {
          positionCode: resolved.positionCode,
          targetGradeCode: resolved.targetGradeCode,
          jobDescription: resolved.jobDescription,
        },
        gradeGuide: {
          id: resolved.gradeGuideId,
          version: resolved.gradeGuideVersion,
        },
        score: {
          overall: Number(resolved.overallScore),
          minimumRequired: Number(resolved.minimumOverallScore),
          thresholdMet: resolved.thresholdMet === true,
          mandatoryDimensionsMet:
            resolved.mandatoryDimensionsMet === true,
        },
        decision: resolved.decision,
        dimensionAssessments: resolved.dimensionAssessments,
        reviewReasons: resolved.reviewReasons,
        modelWarnings: resolved.modelWarnings,
        assessmentSummary: resolved.assessmentSummary,
        execution: {
          attemptCount: Number(resolved.attemptCount),
          status: resolved.executionStatus,
          replayed: false,
          startedAt: asIsoDate(resolved.startedAt, 'startedAt'),
          completedAt: asIsoDate(resolved.completedAt, 'completedAt'),
        },
        metadata: {
          scoringModel: resolved.scoringModel,
          promptVersion: resolved.promptVersion,
          engineVersion: resolved.engineVersion,
          assessmentStatus: resolved.assessmentStatus,
          createdAt: asIsoDate(
            resolved.assessmentCreatedAt,
            'assessmentCreatedAt'
          ),
        },
      },
    },
  },
];

const persisted = $input.first().json;

if (
  !persisted.questionSetId ||
  persisted.round !== 'FIRST' ||
  Number(persisted.questionCount) < 1
) {
  throw new Error(
    'FIRST_QUESTION_SET_PERSISTENCE_FAILED'
  );
}

const validated =
  $('Validate Interview Questions').first().json;

return [
  {
    json: {
      ...validated,
      persistence: {
        sessionId: persisted.sessionId,
        questionSetId: persisted.questionSetId,
        questionSetVersion: Number(persisted.version),
        contentHash: persisted.contentHash,
      },
    },
  },
];

const persisted = $input.first().json;

if (
  persisted.complete !== true ||
  Number(persisted.persistedCount) !==
    Number(persisted.expectedCount)
) {
  throw new Error(
    'FIRST_ROUND_ANSWER_PERSISTENCE_FAILED'
  );
}

const normalized =
  $('Normalize Interview Answers').first().json;

return [
  {
    json: {
      ...normalized,
      persistence: {
        sessionId: persisted.sessionId,
        questionSetId: persisted.questionSetId,
        answerCount: Number(persisted.persistedCount),
      },
    },
  },
];

const persisted = $input.first().json;

if (
  !persisted.questionSetId ||
  persisted.round !== 'FOLLOW_UP' ||
  Number(persisted.questionCount) < 1
) {
  throw new Error(
    'FOLLOW_UP_QUESTION_SET_PERSISTENCE_FAILED'
  );
}

const validated =
  $('Validate Follow-up Questions').first().json;

return [
  {
    json: {
      ...validated,
      persistence: {
        sessionId: persisted.sessionId,
        questionSetId: persisted.questionSetId,
        questionSetVersion: Number(persisted.version),
        contentHash: persisted.contentHash,
      },
    },
  },
];

const persisted = $input.first().json;

if (
  persisted.complete !== true ||
  Number(persisted.persistedCount) !==
    Number(persisted.expectedCount)
) {
  throw new Error(
    'FOLLOW_UP_ANSWER_PERSISTENCE_FAILED'
  );
}

const normalized =
  $('Normalize Follow-up Answers').first().json;

return [
  {
    json: {
      ...normalized,
      persistence: {
        sessionId: persisted.sessionId,
        questionSetId: persisted.questionSetId,
        answerCount: Number(persisted.persistedCount),
      },
    },
  },
];

const persisted = $input.first().json;

if (
  persisted.complete !== true ||
  Number(persisted.answerCount) !==
    Number(persisted.evaluatedCount)
) {
  throw new Error(
    'ANSWER_EVALUATION_PERSISTENCE_FAILED'
  );
}

const validated =
  $('Validate Answer Scores').first().json;

return [
  {
    json: {
      ...validated,
      persistence: {
        sessionId: persisted.sessionId,
        answerCount: Number(persisted.answerCount),
      },
    },
  },
];

const persisted = $input.first().json;

let result = persisted.resultPayload;

if (typeof result === 'string') {
  result = JSON.parse(result);
}

if (
  !result ||
  typeof result !== 'object' ||
  Array.isArray(result) ||
  !persisted.sessionId ||
  !persisted.resultId
) {
  throw new Error(
    'COMPLETED_INTERVIEW_RESULT_NOT_AVAILABLE'
  );
}

const replayed =
  persisted.wasInserted === undefined
    ? true
    : persisted.wasInserted !== true;

return [
  {
    json: {
      ...result,
      persistence: {
        sessionId: persisted.sessionId,
        resultId: persisted.resultId,
        resultVersion: Number(persisted.resultVersion),
        attemptCount: Number(persisted.attemptCount),
        replayed,
      },
    },
  },
];
